-- Phase 26: platform campaigns, campaign opt-ins and the Ad Marketplace price list (SPEC core 7
-- and 8). The types, tables and indexes are generated by drizzle-kit; the triggers at the end are
-- hand-added and hold the rules no CHECK can express:
--   * a campaign's seven terms (dates included) change only together with terms_version + 1,
--     and a raised version voids every ACTIVE opt-in in the same statement;
--   * an opt-in is created only by the shop's own account, for the campaign's current terms
--     version, and afterwards can only be closed, once; it is never deleted;
--   * a published ad product's placement, billing model, price and duration never change.
CREATE TYPE "public"."ad_billing_model" AS ENUM('FLAT_RATE', 'PER_ORDER_PREMIUM');--> statement-breakpoint
CREATE TYPE "public"."ad_slot" AS ENUM('CAROUSEL', 'FEED_LISTING');--> statement-breakpoint
CREATE TYPE "public"."campaign_opt_in_status" AS ENUM('ACTIVE', 'OPTED_OUT', 'VOIDED');--> statement-breakpoint
CREATE TYPE "public"."discount_kind" AS ENUM('FLAT', 'PERCENTAGE');--> statement-breakpoint
CREATE TABLE "ad_products" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"name" text NOT NULL,
	"slot" "ad_slot" NOT NULL,
	"billing_model" "ad_billing_model" NOT NULL,
	"price_npr" numeric(12, 2) NOT NULL,
	"duration_days" integer NOT NULL,
	"is_active" boolean DEFAULT true NOT NULL,
	"created_by_user_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "ad_products_name_check" CHECK (btrim("ad_products"."name") <> ''),
	CONSTRAINT "ad_products_price_check" CHECK ("ad_products"."price_npr" > 0),
	CONSTRAINT "ad_products_duration_check" CHECK ("ad_products"."duration_days" BETWEEN 1 AND 90)
);
--> statement-breakpoint
CREATE TABLE "campaign_opt_ins" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"campaign_id" uuid NOT NULL,
	"vendor_id" uuid NOT NULL,
	"opt_in_terms_version" integer NOT NULL,
	"terms_snapshot" jsonb NOT NULL,
	"status" "campaign_opt_in_status" DEFAULT 'ACTIVE' NOT NULL,
	"opted_in_by_user_id" uuid NOT NULL,
	"opted_in_at" timestamp with time zone DEFAULT now() NOT NULL,
	"closed_at" timestamp with time zone,
	"closed_by_user_id" uuid,
	CONSTRAINT "campaign_opt_ins_terms_version_check" CHECK ("campaign_opt_ins"."opt_in_terms_version" >= 1),
	CONSTRAINT "campaign_opt_ins_terms_snapshot_check" CHECK (jsonb_typeof("campaign_opt_ins"."terms_snapshot") = 'object'),
	CONSTRAINT "campaign_opt_ins_closed_check" CHECK (("campaign_opt_ins"."status" = 'ACTIVE') = ("campaign_opt_ins"."closed_at" IS NULL)),
	CONSTRAINT "campaign_opt_ins_closed_by_check" CHECK (("campaign_opt_ins"."status" = 'OPTED_OUT') = ("campaign_opt_ins"."closed_by_user_id" IS NOT NULL))
);
--> statement-breakpoint
CREATE TABLE "platform_campaigns" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"name" text NOT NULL,
	"kind" "discount_kind" NOT NULL,
	"value" numeric(12, 2) NOT NULL,
	"max_discount_npr" numeric(12, 2),
	"min_cart_npr" numeric(12, 2) DEFAULT 0 NOT NULL,
	"vendor_share_percent" numeric(5, 2) NOT NULL,
	"terms_version" integer DEFAULT 1 NOT NULL,
	"starts_at" timestamp with time zone NOT NULL,
	"ends_at" timestamp with time zone NOT NULL,
	"is_active" boolean DEFAULT true NOT NULL,
	"created_by_user_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "platform_campaigns_name_check" CHECK (btrim("platform_campaigns"."name") <> ''),
	CONSTRAINT "platform_campaigns_value_check" CHECK ("platform_campaigns"."value" > 0 AND ("platform_campaigns"."kind" <> 'PERCENTAGE' OR "platform_campaigns"."value" <= 100)),
	CONSTRAINT "platform_campaigns_max_discount_check" CHECK ("platform_campaigns"."max_discount_npr" IS NULL OR ("platform_campaigns"."kind" = 'PERCENTAGE' AND "platform_campaigns"."max_discount_npr" > 0)),
	CONSTRAINT "platform_campaigns_min_cart_check" CHECK ("platform_campaigns"."min_cart_npr" >= 0),
	CONSTRAINT "platform_campaigns_vendor_share_check" CHECK ("platform_campaigns"."vendor_share_percent" BETWEEN 0 AND 100),
	CONSTRAINT "platform_campaigns_dates_check" CHECK ("platform_campaigns"."ends_at" > "platform_campaigns"."starts_at"),
	CONSTRAINT "platform_campaigns_terms_version_check" CHECK ("platform_campaigns"."terms_version" >= 1)
);
--> statement-breakpoint
ALTER TABLE "ad_products" ADD CONSTRAINT "ad_products_created_by_user_id_users_id_fk" FOREIGN KEY ("created_by_user_id") REFERENCES "public"."users"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "campaign_opt_ins" ADD CONSTRAINT "campaign_opt_ins_campaign_id_platform_campaigns_id_fk" FOREIGN KEY ("campaign_id") REFERENCES "public"."platform_campaigns"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
