ALTER TABLE "campaign_opt_ins" ADD CONSTRAINT "campaign_opt_ins_opted_in_by_user_id_users_id_fk" FOREIGN KEY ("opted_in_by_user_id") REFERENCES "public"."users"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "campaign_opt_ins" ADD CONSTRAINT "campaign_opt_ins_closed_by_user_id_users_id_fk" FOREIGN KEY ("closed_by_user_id") REFERENCES "public"."users"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "platform_campaigns" ADD CONSTRAINT "platform_campaigns_created_by_user_id_users_id_fk" FOREIGN KEY ("created_by_user_id") REFERENCES "public"."users"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "ad_products_created_by_user_id_idx" ON "ad_products" USING btree ("created_by_user_id");--> statement-breakpoint
CREATE UNIQUE INDEX "campaign_opt_ins_active_uidx" ON "campaign_opt_ins" USING btree ("campaign_id","vendor_id") WHERE "campaign_opt_ins"."status" = 'ACTIVE';--> statement-breakpoint
CREATE INDEX "campaign_opt_ins_campaign_id_idx" ON "campaign_opt_ins" USING btree ("campaign_id","status");--> statement-breakpoint
CREATE INDEX "campaign_opt_ins_vendor_id_idx" ON "campaign_opt_ins" USING btree ("vendor_id","opted_in_at");--> statement-breakpoint
CREATE INDEX "campaign_opt_ins_opted_in_by_user_id_idx" ON "campaign_opt_ins" USING btree ("opted_in_by_user_id");--> statement-breakpoint
