-- Hand-added from here --------------------------------------------------------------------
CREATE TRIGGER platform_campaigns_set_updated_at BEFORE UPDATE ON platform_campaigns
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();
--> statement-breakpoint
-- Terms are versioned. A campaign starts at version 1; a change to any of the seven terms must
-- raise the version by exactly 1, and the version moves for no other reason (the name and
-- is_active are not terms).
CREATE FUNCTION enforce_campaign_terms_version() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  terms_changed boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.terms_version <> 1 THEN
      RAISE EXCEPTION 'a campaign starts at terms_version 1'
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
  END IF;
  terms_changed :=
    (NEW.kind, NEW.value, NEW.max_discount_npr, NEW.min_cart_npr, NEW.vendor_share_percent,
     NEW.starts_at, NEW.ends_at)
    IS DISTINCT FROM
    (OLD.kind, OLD.value, OLD.max_discount_npr, OLD.min_cart_npr, OLD.vendor_share_percent,
     OLD.starts_at, OLD.ends_at);
  IF terms_changed AND NEW.terms_version <> OLD.terms_version + 1 THEN
    RAISE EXCEPTION 'campaign terms change only together with terms_version + 1'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF NOT terms_changed AND NEW.terms_version <> OLD.terms_version THEN
    RAISE EXCEPTION 'terms_version changes only when the campaign terms do'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER platform_campaigns_terms_version BEFORE INSERT OR UPDATE ON platform_campaigns
  FOR EACH ROW EXECUTE FUNCTION enforce_campaign_terms_version();
--> statement-breakpoint
-- New terms void the consent given to the old ones: no order is ever discounted under terms a
-- vendor did not accept. The shop opts in again to the new version.
CREATE FUNCTION void_stale_campaign_opt_ins() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  UPDATE campaign_opt_ins
     SET status = 'VOIDED', closed_at = now()
   WHERE campaign_id = NEW.id AND status = 'ACTIVE';
  RETURN NULL;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER platform_campaigns_void_opt_ins AFTER UPDATE ON platform_campaigns
  FOR EACH ROW WHEN (NEW.terms_version <> OLD.terms_version)
  EXECUTE FUNCTION void_stale_campaign_opt_ins();
--> statement-breakpoint
-- An opt-in is the vendor's own consent.
CREATE FUNCTION guard_campaign_opt_in() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  shop_user_id uuid;
  current_version integer;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'campaign_opt_ins rows are never deleted'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'ACTIVE' THEN
      RAISE EXCEPTION 'an opt-in is created ACTIVE'
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    -- An unknown vendor or campaign is left to its foreign key.
    SELECT user_id INTO shop_user_id FROM vendors WHERE id = NEW.vendor_id;
    IF FOUND AND shop_user_id <> NEW.opted_in_by_user_id THEN
      RAISE EXCEPTION 'only the shop''s own account can opt it in to a campaign'
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    -- FOR SHARE: a terms change running now waits for this opt-in, or this waits for it; either
    -- way the version compared here is the one the opt-in commits against.
    SELECT terms_version INTO current_version
      FROM platform_campaigns WHERE id = NEW.campaign_id FOR SHARE;
    IF FOUND AND NEW.opt_in_terms_version <> current_version THEN
      RAISE EXCEPTION 'the campaign terms changed (current terms_version is %)', current_version
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.status <> 'ACTIVE' THEN
    RAISE EXCEPTION 'a closed opt-in never changes'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF (NEW.id, NEW.campaign_id, NEW.vendor_id, NEW.opt_in_terms_version, NEW.terms_snapshot,
      NEW.opted_in_by_user_id, NEW.opted_in_at)
     IS DISTINCT FROM
     (OLD.id, OLD.campaign_id, OLD.vendor_id, OLD.opt_in_terms_version, OLD.terms_snapshot,
      OLD.opted_in_by_user_id, OLD.opted_in_at) THEN
    RAISE EXCEPTION 'an opt-in records what was agreed: it can only be closed'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF NEW.status = 'OPTED_OUT' THEN
    SELECT user_id INTO shop_user_id FROM vendors WHERE id = NEW.vendor_id;
    IF NEW.closed_by_user_id IS DISTINCT FROM shop_user_id THEN
      RAISE EXCEPTION 'only the shop''s own account can opt it out of a campaign'
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER campaign_opt_ins_guard BEFORE INSERT OR UPDATE OR DELETE ON campaign_opt_ins
  FOR EACH ROW EXECUTE FUNCTION guard_campaign_opt_in();
--> statement-breakpoint
-- A price vendors bought at is never rewritten. Only the name and is_active may change.
CREATE FUNCTION reject_ad_product_terms_change() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF (NEW.slot, NEW.billing_model, NEW.price_npr, NEW.duration_days)
     IS DISTINCT FROM (OLD.slot, OLD.billing_model, OLD.price_npr, OLD.duration_days) THEN
    RAISE EXCEPTION 'a published ad product''s placement, billing model, price and duration never change'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER ad_products_immutable_terms BEFORE UPDATE ON ad_products
  FOR EACH ROW EXECUTE FUNCTION reject_ad_product_terms_change();
